// good looking on dark AND white bg\n$action-background-hover: rgba(127, 127, 127, .25);\n\n// various structure data used in the\n// `NcAppNavigation` component\n$header-height: 50px;\n$navigation-width: 300px;\n\n// mobile breakpoint\n$breakpoint-mobile: 1024px;\n\n//messages list max width\n$messages-list-max-width: 800px;\n\n//message max width\n$message-max-width: 680px;\n\n//message utils width\n$message-utils-width: 100px;\n\n//message form max height\n$message-form-max-height: 180px;\n\n$color-call-background: rgba(34, 34, 34, 0.8);\n$color-guests-avatar: #ffffff;\n$color-background-guests-avatar: #b9b9b9;\n\n\n//chat font size\n$chat-font-size: 15px;\n\n//chat line height\n$chat-line-height: 1.6em;\n\n// fade transition\n$fade-transition: all var(--animation-quick, 100ms) ease-in-out;\n$fade-transition-slow: all var(--animation-slow, 300ms) ease-in-out;\n\n.fade {\n\t&-enter {\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\ttransition: $fade-transition;\n\t}\n}\n\n.slide-down {\n\t&-enter {\n\t\ttransform: translateY(50%);\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\ttransform: translateY(50%);\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\ttransition: $fade-transition;\n\t\t/* force top container to resize during animation */\n\t\tposition: absolute !important;\n\t}\n}\n","/**\n * @copyright Copyright (c) 2020 Joas Schilling <coding@schilljs.com>\n *\n * @author Joas Schilling <coding@schilljs.com>\n *\n * @license GNU AGPL version 3 or any later version\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU Affero General Public License as\n * published by the Free Software Foundation, either version 3 of the\n * License, or (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU Affero General Public License for more details.\n *\n * You should have received a copy of the GNU Affero General Public License\n * along with this program. If not, see <http://www.gnu.org/licenses/>.\n *\n */\n@use 'sass:math';\n\n@import 'variables';\n\n\n@mixin avatar-mixin($size: 32px) {\n\t.avatar-#{$size} {\n\t\tposition: sticky;\n\t\ttop: 0;\n\t\twidth: $size;\n\t\theight: $size;\n\t\tline-height: $size;\n\t\tfont-size: math.div($size, 2);\n\t\tborder-radius: 50%;\n\n\t\t&.icon {\n\t\t\tborder-radius: 50%;\n\t\t\theight: $size;\n\t\t\twidth: $size;\n\t\t\tbackground-color: var(--color-background-darker);\n\t\t}\n\n\t\t&.bot {\n\t\t\tpadding-left: 5px;\n\t\t\tline-height: $size;\n\t\t\tborder-radius: 50%;\n\t\t\tbackground-color: var(--color-background-darker);\n\t\t}\n\n\t\t&.guest {\n\t\t\tline-height: $size;\n\t\t\tfont-size: math.div($size, 2);\n\t\t\tcolor: $color-guests-avatar;\n\t\t\tbackground-color: $color-background-guests-avatar;\n\t\t\tpadding: 0;\n\t\t\tdisplay: block;\n\t\t\ttext-align: center;\n\t\t\tmargin-left: auto;\n\t\t\tmargin-right: auto;\n\t\t}\n\t}\n}\n","\n@import '../../../assets/variables';\n@import '../../../assets/avatar';\n@include avatar-mixin(64px);\n@include avatar-mixin(128px);\n\n.not-connected {\n\tvideo,\n\t.avatar-container {\n\t\topacity: 0.5;\n\t}\n}\n\n.video-container-grid {\n\tposition:relative;\n\theight: 100%;\n\twidth: 100%;\n\toverflow: hidden;\n\tdisplay: flex;\n\tflex-direction: column;\n}\n\n.video-container-stripe:not(.local-video--sidebar) {\n\t// aspect-ratio is set according to the maximum video resolution after applying constraints (720*540)\n\t--aspect-ratio: 1.33333;\n\t--stripe-height: 242px;\n\tposition: relative;\n\tflex: 0 0 calc(var(--aspect-ratio) * var(--stripe-height));\n\toverflow: hidden;\n\tdisplay: flex;\n\tflex-direction: column;\n\tmargin-top: auto;\n\theight: var(--stripe-height) !important;\n}\n\n.video-container-big {\n\tposition: absolute;\n\twidth: calc(100% - 16px);\n\theight: calc(100% - 8px);\n\tdisplay: flex;\n\tflex-direction: column;\n\n\t& .videoWrapper {\n\t\tmargin: auto;\n\t}\n}\n\n.videoWrapper,\n.video {\n\theight: 100%;\n\twidth: 100%;\n}\n\n.videoWrapper.icon-loading:after {\n\theight: 60px;\n\twidth: 60px;\n\tmargin: -32px 0 0 -32px;\n}\n\n.video--fit {\n\t/* Fit the frame */\n\tobject-fit: contain;\n}\n\n.video--fill {\n\t/* Fill the frame */\n\tobject-fit: cover;\n}\n\n.avatar-container {\n\tmargin: auto;\n}\n\n.hover-shadow {\n\tposition: absolute;\n\theight: 100%;\n\twidth: 100%;\n\ttop: 0;\n\tleft: 0;\n\tbox-shadow: inset 0 0 0 3px white;\n\tcursor: pointer;\n\tborder-radius: calc(var(--default-clickable-area)/2);\n}\n\n.bottom-bar {\n\tposition: absolute;\n\tbottom: 0;\n\twidth: 100%;\n\tpadding: 0 20px 12px 24px;\n\tdisplay: flex;\n\tjustify-content: center;\n\talign-items: center;\n\theight: 40px;\n\t&--big {\n\t\tjustify-content: center;\n\t\theight: 48px;\n\t}\n\t& &__button {\n\t\topacity: 0.8;\n\t\tbackground-color: var(--color-background-dark);\n\t\t&:hover,\n\t\t&:focus {\n\t\t\topacity: 1;\n\t\t}\n\t}\n}\n\n// Always display the local video in the last row\n#localVideoContainer {\n\tgrid-row-end: -1;\n\tborder-radius: calc(var(--default-clickable-area)/2);\n\tz-index: 1;\n}\n\n"],sourceRoot:""}]);const s=o},20802:(e,t,n)=>{"use strict";n.d(t,{Z:()=>s});var r=n(87537),a=n.n(r),i=n(23645),o=n.n(i)()(a());o.push([e.id,".screen[data-v-5547c1f7]{width:100%;height:100%;position:absolute;top:0;left:0}.screen--fit[data-v-5547c1f7]{object-fit:contain}.screen--fill[data-v-5547c1f7]{object-fit:cover}","",{version:3,sources:["webpack://./src/components/CallView/shared/Screen.vue"],names:[],mappings:"AAEA,yBACC,UAAA,CACA,WAAA,CACA,iBAAA,CACA,KAAA,CACA,MAAA,CACA,8BACC,kBAAA,CAED,+BAC